		return
	}
	if n.Sz[ra] < n.Sz[rb] {
		ra, rb = rb, ra
	}
	n.Par[rb] = ra
	n.Sz[ra] += n.Sz[rb]
}

func OpTie(toks []string) *Net {
	n := NewNet()
	for _, t := range toks {
		n.Add(t)
	}
	return n
}

// OpMark returns the bytewise-least token in tok's connected component.
// Go string comparison is lexicographic by byte, which is the required UTF-8
// byte ordering.
func OpMark(n *Net, tok string) string {
	root := n.Find(tok)
	mark := tok
	for k := range n.Par {
		if n.Find(k) == root && k < mark {
			mark = k
		}
	}
	return mark
}
