package cardpit

import (
	"errors"
	"os"
	"path/filepath"
	"strings"

	"berth.local/twinefuse/netsrc"
)

func NPair(dir string, n *netsrc.Net) error {
	ents, err := os.ReadDir(dir)
	if err != nil {
		return err
	}
	for _, ent := range ents {
		if ent.IsDir() || !strings.HasSuffix(ent.Name(), ".cue") {
			continue
		}
		body, err := os.ReadFile(filepath.Join(dir, ent.Name()))
		if err != nil {
			return err
		}
		left, right, origin := "", "", ""
		for _, line := range strings.Split(string(body), "\n") {
			line = strings.TrimSpace(line)
			if line == "" || !strings.Contains(line, "=") {
				continue
			}
			k, v, _ := strings.Cut(line, "=")
			switch strings.TrimSpace(k) {
			case "left":
				left = strings.TrimSpace(v)
			case "right":
				right = strings.TrimSpace(v)
			case "origin":
				origin = strings.TrimSpace(v)
			}
		}
		if origin == "scrapped" {
			return errors.New("scrapped pair: " + ent.Name())
		}
		if left != "" && right != "" {
			n.Join(left, right)
		}
	}
	return nil
}
