package walkbind

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type Row struct {
	Id    string `json:"id"`
	Hitch string `json:"hitch"`
	Tok   string `json:"tok"`
}

func CfgStamp(outDir string, rows []Row) error {
	if err := os.MkdirAll(outDir, 0o755); err != nil {
		return err
	}
	rf, err := os.Create(filepath.Join(outDir, "rows.ndjson"))
	if err != nil {
		return err
	}
	enc := json.NewEncoder(rf)
	enc.SetEscapeHTML(false)
	for _, row := range rows {
		if err := enc.Encode(row); err != nil {
			rf.Close()
			return err
		}
	}
	if err := rf.Close(); err != nil {
		return err
	}

	groups := make(map[string]map[string]struct{})
	for _, row := range rows {
		if groups[row.Hitch] == nil {
			groups[row.Hitch] = make(map[string]struct{})
		}
		groups[row.Hitch][row.Id] = struct{}{}
	}
	hitches := make([]string, 0, len(groups))
	for hitch := range groups {
		hitches = append(hitches, hitch)
	}
	sort.Strings(hitches)

	xf, err := os.Create(filepath.Join(outDir, "hitch.idx"))
	if err != nil {
		return err
	}
	for _, hitch := range hitches {
		ids := make([]string, 0, len(groups[hitch]))
		for id := range groups[hitch] {
			ids = append(ids, id)
		}
		sort.Strings(ids)
		if _, err := xf.WriteString(hitch + " " + strings.Join(ids, ",") + "\n"); err != nil {
			xf.Close()
			return err
		}
	}
	if err := xf.Close(); err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(outDir, "berth.ok"), []byte("ok\n"), 0o644)
}
EOF

